const scores = {
    math: 90,
    english: 85,
    physics: 95
};

const values = Object.values(scores);

let sum = 0;

for (const value of values) {
    sum += value;
}

console.log(sum);

const user = {
    name: "Alex",
    age: 25,
    city: "London"
};

const entries = Object.entries(user);

console.log(entries);

const user = {
    name: "Alex",
    age: 25,
    city: "London"
};

for (const [key, value] of Object.entries(user)) {
    console.log(key, value);
}
